INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (1, 1, 'Объект использования атомной энергии (в том числе ядерные установки, пункты хранения ядерных материалов и радиоактивных веществ, пункты хранения радиоактивных отходов)');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (2, 2, 'Гидротехнические сооружения первого и второго классов, устанавливаемые в соответствии с законодательством о безопасности гидротехнических сооружений');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (3, 3, 'Сооружения связи, являющиеся особо опасными, технически сложными в соответствии с законодательством Российской Федерации в области связи');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (4, 4, 'Линия электропередачи и иные объекты электросетевого хозяйства напряжением 330 киловольт и более');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (5, 5, 'Объект космической инфраструктуры');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (6, 6, 'Объект авиационной инфраструктуры');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (7, 7, 'Объекты инфраструктуры железнодорожного транспорта общего пользования');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (8, 8, 'Метрополитен');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (9, 9, 'Морской порт, за исключением объектов инфраструктуры морского порта, предназначенных для стоянок и обслуживания маломерных, спортивных парусных и прогулочных судов');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (10, 10, 'Тепловая электростанция мощностью 150 мегаватт и выше');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (11, 11, 'Подвесная канатная дорога');
INSERT INTO fiz.danger_obj (objectid, code, description) VALUES (12, 12, 'Опасный производственный объект, подлежащий регистрации в государственном реестре в соответствии с законодательством Российской Федерации о промышленной безопасности опасных производственных объектов');
